    return (BE ? (v[0] << 24) : (v[0]      ))
	 + (BE ? (v[1] << 16) : (v[1] <<  8))
	 + (BE ? (v[2] <<  8) : (v[2] << 16))
	 + (BE ? (v[3]      ) : (v[3] << 24));
