typedef NumType<false, uint32_t> HBUINT32LE;
typedef NumType<false, int32_t>  HBINT32LE;
typedef NumType<false, uint64_t> HBUINT64LE;
typedef NumType<false, int64_t>  HBINT64LE;

typedef NumType<true,  float>  HBFLOAT32BE;
