hb_font_set_user_data (hb_font_t          *font,
		       hb_user_data_key_t *key,
		       void *              data,
		       hb_destroy_func_t   destroy ,
		       hb_bool_t           replace)
{
  if (!hb_object_is_immutable (font))
    font->changed ();

  return hb_object_set_user_data (font, key, data, destroy, replace);
}

